options.onMounted:
this.globalOptionData.fileList = []
this.globalOptionData.folderList = []
$api.get('/api/dms/docpal-type/active', {}).then(res => {
  res = res.data.data
  res.forEach((item) => {
    const _item = {
      value: item.name,
      label: item.name ? $t(item.name) : '',
      keywords: item.keywords
    }
    if(item.isFolder) {
      this.globalOptionData.folderList.push(_item)
    } else {
      this.globalOptionData.fileList.push(_item)
    }
  })
  this.loadOptions(this.globalOptionData.folderList)
}).catch(err => {
  console.log("error", err)
})

const _this = this
const needUserList = [
  'notificationReminder.tos',
  'emailReminder.tos',
  'emailReminder.ccs',
  'emailReport.tos',
  'emailReport.ccs'
]
$api.get('/users/select', { baseURL: '/gateway/v1' }).then(res => {
  res = res.data.data
  const result = []
  res.forEach(item => {
    if(item.value) {
      result.push({
        label: item.label,
        value: item.value
      })
    }
  })
  result.sort((a, b) => a.label.localeCompare(b.label))
  result.unshift({
     value: 'createBy',
     label: $t('role.creator')
  })
  needUserList.forEach(key => {
    const keyRef = _this.getWidgetRef(key)
    if(!!keyRef) keyRef.loadOptions(result)
  })
}).catch(err => {
})
